class Solution:
    def scheduleCourse(self, courses: list[list[int]]) -> int:
        courses.sort(key=lambda x: x[1])
        limit = max(d for _, d in courses)
        dp = [-10**9] * (limit + 1)
        dp[0] = 0
        for duration, last in courses:
            for t in range(last, duration - 1, -1):
                dp[t] = max(dp[t], dp[t - duration] + 1)
        return max(dp)

