class Solution:
    def scheduleCourse(self, courses: list[list[int]]) -> int:
        courses.sort(key=lambda x: x[1])
        n = len(courses)
        inf = 10**18
        dp = [0] + [inf] * n
        best = 0
        for duration, last in courses:
            for k in range(best, -1, -1):
                if dp[k] + duration <= last and dp[k] + duration < dp[k + 1]:
                    dp[k + 1] = dp[k] + duration
                    best = max(best, k + 1)
        return best

