class Solution:
    def scheduleCourse(self, courses: list[list[int]]) -> int:
        import heapq
        total = 0
        heap = []
        for duration, last in sorted(courses, key=lambda x: x[1]):
            total += duration
            heapq.heappush(heap, -duration)
            if total > last:
                total += heapq.heappop(heap)
        return len(heap)

